def solve_coin_flipping(n):
    N = 2 * n + 1

    # Dictionary to store the flip count for each coin index
    flip_counts = {i: 0 for i in range(N)}

    # The sequence of flips runs from k=1 to k=N
    for k in range(1, N + 1):
        # The index P_k is the k-th triangular number modulo N: P_k = k(k+1)/2 mod N
        p_k = (k * (k + 1) // 2) % N

        # Increment the flip count for this coin
        flip_counts[p_k] += 1

    # Count the number of coins flipped an odd number of times (Heads Down)
    heads_down_count = 0
    for count in flip_counts.values():
        if count % 2 != 0:
            heads_down_count += 1

    return heads_down_count

# Calculate for n=1, n=2, n=3
results = {}
for n in [1, 2, 3]:
    results[n] = solve_coin_flipping(n)

print(f"Results: {results}")

